class Word {
    String _name;  // Member object
    int _cnt;     // Primitive member
public:
    // Correct syntax with initializer list:
    Word() : _name(0), _cnt(0) {}  // Compiler synthesizes call to String's constructor with argument 0 before body

    // Incorrect syntax (pitfall, especially in templates):
    Word() {  // Compiler first default-constructs _name if possible
        _name.String::String(0);  // Manual call, which may cause double initialization
        _cnt = 0;  // Direct assignment
    }  // Note: In templates, if String is a template parameter, this could fail at instantiation time due to dependent names.
};

