#include <string>
#include <iostream>
template <typename T>
class Word {
    T _name;  // T could be std::string or another type
    int _cnt;
public:
    // Potential pitfall: Constructor with in-body initialization
    Word() {
        _name = T(0);  // This is an assignment, not construction; assumes T has a constructor taking int
        _cnt = 0;
    }
    void display() { std::cout << _name << std::endl; }
};
// Correct version using initializer list
template <typename T>
class WordCorrect {
    T _name;
    int _cnt;
public:
    WordCorrect() : _name(0), _cnt(0) {}  // Compiler synthesizes proper construction
    void display() { std::cout << _name << std::endl; }
};
int main() {
    Word<std::string> w;  // May trigger pitfalls if T's constructor isn't handled correctly
    WordCorrect<std::string> wCorrect;
    return 0;
}
